{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    edges = []
    for a, b, d in dists:
        w = max(core[a], core[b], d)
        if a < b:
            edges.append((w, a, b))
        else:
            edges.append((w, b, a))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst = []
    total = 0.0
    for w, a, b in edges:
        if union(a, b):
            mst.append([a, b, w])
            total += w
            if len(mst) == len(nodes) - 1:
                break
    if len(mst) != len(nodes) - 1 and len(nodes) > 0:
        raise ValueError('Graph is disconnected')
    return {'mst_edges': mst, 'total_weight': total}
"}
